import{_ as a,o,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Acerca de y actualizaciones","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/about.md","filePath":"es-ES/user-guide/settings/about.md","lastUpdated":1787586465000}'),s={name:"es-ES/user-guide/settings/about.md"};function n(t,e,d,c,l,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="acerca-de-y-actualizaciones" tabindex="-1">Acerca de y actualizaciones <a class="header-anchor" href="#acerca-de-y-actualizaciones" aria-label="Permalink to &quot;Acerca de y actualizaciones&quot;">​</a></h1><p>La página Acerca de muestra las versiones de los componentes, ofrece acceso directo a las carpetas de datos de usuario y sistema, y permite buscar actualizaciones y aplicar actualizaciones silenciosas. La página se encuentra en <strong>Configuración → Acerca de</strong>.</p><h2 id="_1-versiones-de-componentes-e-informacion" tabindex="-1">1. Versiones de componentes e información <a class="header-anchor" href="#_1-versiones-de-componentes-e-informacion" aria-label="Permalink to &quot;1. Versiones de componentes e información&quot;">​</a></h2><p>La parte superior detalla las versiones independientes de los cuatro componentes principales de Lertaro:</p><ul><li><strong>Versión de App</strong>: Interfaz de usuario WPF en primer plano.</li><li><strong>Versión de Core</strong>: Librería central de búsqueda e indexación.</li><li><strong>Versión de Service</strong>: Servicio de indexación de Windows en segundo plano (el color refleja el estado de conexión del servicio).</li><li><strong>Versión de CLI</strong>: Utilidad interactiva de línea de comandos <code>lff</code>.</li></ul><p>Más abajo se incluyen enlaces al sitio web oficial, al repositorio de GitHub y a la documentación en línea.</p><h2 id="_2-directorios-de-datos-y-rotacion-de-5-copias-de-seguridad" tabindex="-1">2. Directorios de datos y rotación de 5 copias de seguridad <a class="header-anchor" href="#_2-directorios-de-datos-y-rotacion-de-5-copias-de-seguridad" aria-label="Permalink to &quot;2. Directorios de datos y rotación de 5 copias de seguridad&quot;">​</a></h2><p>Enlaces interactivos para abrir los directorios de almacenamiento en el Explorador (las carpetas se crean automáticamente si no existen):</p><h3 id="directorio-de-datos-de-usuario" tabindex="-1">Directorio de datos de usuario <a class="header-anchor" href="#directorio-de-datos-de-usuario" aria-label="Permalink to &quot;Directorio de datos de usuario&quot;">​</a></h3><ul><li><strong>Contenido</strong>: Configuración personal (<code>user-settings.json</code>), historial de búsqueda y palabras clave, cachés y certificados de seguridad.</li><li><strong>Rotación de 5 copias de seguridad</strong>: Cada vez que se guarda la configuración, Lertaro crea automáticamente una copia de respaldo <code>user-settings.json.bak.1</code>, conservando hasta <code>.bak.5</code>. Ante cualquier fallo o corte de energía, se puede restaurar cualquiera de las últimas 5 copias.</li></ul><h3 id="directorio-de-datos-de-equipo-machine" tabindex="-1">Directorio de datos de equipo (Machine) <a class="header-anchor" href="#directorio-de-datos-de-equipo-machine" aria-label="Permalink to &quot;Directorio de datos de equipo (Machine)&quot;">​</a></h3><ul><li><strong>Contenido</strong>: Ajustes del servicio (<code>machine-settings.json</code>), caché persistente del índice de disco y registros del servicio.</li></ul><h3 id="estructura-de-rutas-de-almacenamiento" tabindex="-1">Estructura de rutas de almacenamiento <a class="header-anchor" href="#estructura-de-rutas-de-almacenamiento" aria-label="Permalink to &quot;Estructura de rutas de almacenamiento&quot;">​</a></h3><ul><li><strong>Versión instalable</strong>: Los datos de usuario se guardan en <code>%LocalAppData%\\Lertaro</code> y los de máquina en <code>%ProgramData%\\Lertaro</code>.</li><li><strong>Versión portátil</strong>: Los datos se guardan en <code>Data\\Users\\&lt;SID hash&gt;</code> y <code>Data\\Machine</code> junto al ejecutable (ver <a href="./../getting-started.html#arquitectura-de-aislamiento-de-datos-en-version-portatil"><strong>Aislamiento de datos en versión portátil</strong></a>).</li></ul><h2 id="_3-comprobacion-y-aplicacion-de-actualizaciones" tabindex="-1">3. Comprobación y aplicación de actualizaciones <a class="header-anchor" href="#_3-comprobacion-y-aplicacion-de-actualizaciones" aria-label="Permalink to &quot;3. Comprobación y aplicación de actualizaciones&quot;">​</a></h2><ul><li><strong>Buscar actualizaciones</strong>: Consulta en línea nuevas versiones con información dinámica en el propio botón (&quot;Buscando actualizaciones...&quot; → &quot;Ya tienes la última versión&quot; o detalles de la nueva versión).</li><li><strong>Vías de actualización</strong>: <ul><li><strong>Actualización silenciosa</strong> —— Descarga e instala en segundo plano, reiniciando Lertaro de forma transparente.</li><li><strong>Ir a la página de descargas</strong> —— Abre la página de lanzamientos de GitHub en el navegador predeterminado para su descarga manual.</li></ul></li><li><strong>Avisos de permisos</strong>: Si se ejecuta con una cuenta sin permisos de administrador para reiniciar el servicio, un aviso guiará hacia la página de descarga manual.</li></ul>',16)])])}const m=a(s,[["render",n]]);export{g as __pageData,m as default};
